struct PartialOutput{uint64_t device,inode;std::string token,kind;};
static std::map<fs::path,PartialOutput> partialOutputs;
static fs::path partialJournal(){return fs::path(AMPR_STATE_ROOT)/"partial-outputs.json";}
static void removeOwnedTree(const fs::path&path){struct stat st{};if(lstat(path.c_str(),&st)){if(errno==ENOENT)return;throw std::runtime_error("Cannot inspect "+path.u8string()+": "+strerror(errno));}if(!S_ISDIR(st.st_mode)){check(unlink(path.c_str())==0,"Cannot delete file "+path.u8string()+": "+strerror(errno));return;}DIR*directory=opendir(path.c_str());check(directory!=nullptr,"Cannot open folder "+path.u8string()+": "+strerror(errno));try{errno=0;while(auto*entry=readdir(directory)){std::string name=entry->d_name;if(name=="."||name=="..")continue;removeOwnedTree(path/fs::u8path(name));errno=0;}check(errno==0,"Cannot list folder "+path.u8string()+": "+strerror(errno));closedir(directory);directory=nullptr;check(rmdir(path.c_str())==0,"Cannot remove folder "+path.u8string()+": "+strerror(errno));check(lstat(path.c_str(),&st)!=0&&errno==ENOENT,"Folder still exists after removal: "+path.u8string());}catch(...){if(directory)closedir(directory);throw;}}
static void savePartials(){fs::create_directories(partialJournal().parent_path());Json entries=Json::array();for(auto&entry:partialOutputs)entries.push_back(Json{{"path",entry.first.generic_u8string()},{"device",entry.second.device},{"inode",entry.second.inode},{"token",entry.second.token},{"kind",entry.second.kind}});auto temporary=partialJournal();temporary+=".tmp";{std::ofstream file(temporary);check(bool(file),"Cannot save partial-output cleanup record.");file<<entries.dump(2);file.flush();check(bool(file),"Cannot write partial-output cleanup record.");}fs::rename(temporary,partialJournal());}
static void loadPartials(){if(!fs::exists(partialJournal()))return;auto bytes=read(partialJournal());auto entries=Json::parse(bytes);check(entries.is_array()&&entries.size()<=128,"Invalid partial-output cleanup record.");for(auto&entry:entries){auto path=fs::u8path(entry.at("path").get<std::string>());check(path.is_absolute()&&path!=path.root_path(),"Unsafe cleanup record path.");partialOutputs[path]={entry.at("device"),entry.at("inode"),entry.at("token"),entry.at("kind")};}}
static void trackPartial(const fs::path&path,const std::string&kind){struct stat st{};check(lstat(path.c_str(),&st)==0&&S_ISDIR(st.st_mode),"Cannot identify owned partial folder.");auto canonical=fs::canonical(path);auto found=partialOutputs.find(canonical);if(found==partialOutputs.end()){std::string token="AMPRStudio:"+std::to_string(ioClock())+":"+std::to_string(st.st_ino);{std::ofstream marker(canonical/".ampr-owned");marker<<token;marker.flush();check(bool(marker),"Cannot mark owned partial folder.");}partialOutputs[canonical]={uint64_t(st.st_dev),uint64_t(st.st_ino),token,kind};savePartials();}}
static void forgetPartial(const fs::path&path){auto canonical=fs::weakly_canonical(path);partialOutputs.erase(canonical);savePartials();std::error_code ec;fs::remove(canonical/".ampr-owned",ec);}
extern "C" void ampr_backend_partial_info(char*out,size_t size){std::unique_lock<std::mutex> guard(backendLock,std::try_to_lock);Json paths=Json::array();if(guard.owns_lock()){try{loadPartials();for(auto&entry:partialOutputs)paths.push_back(entry.first.generic_u8string());}catch(const std::exception&e){snprintf(out,size,"[]");return;}}snprintf(out,size,"%s",paths.dump().c_str());}
static std::mutex metricsLock;static std::string metricsStage;static uint64_t metricsStarted=0,metricsEnded=0;static Json metricsHistory=Json::array();
static Json metricsSnapshot(){double seconds=metricsStarted?double((metricsEnded?metricsEnded:ioClock())-metricsStarted)/1e9:0;unsigned workers=ioMetrics.workers.load();return Json{{"phase",metricsStage},{"seconds",seconds},{"readBytes",ioMetrics.readBytes.load()},{"writtenBytes",ioMetrics.writeBytes.load()},{"readMiBps",seconds?ioMetrics.readBytes.load()/1048576.0/seconds:0},{"writeMiBps",seconds?ioMetrics.writeBytes.load()/1048576.0/seconds:0},{"workers",workers},{"readers",ioMetrics.readers.load()},{"writers",ioMetrics.writers.load()},{"coordinator",1},{"pipelineThreads",1+ioMetrics.readers.load()+workers+ioMetrics.writers.load()},{"readIoSeconds",ioMetrics.readNs.load()/1e9},{"writeIoSeconds",ioMetrics.writeNs.load()/1e9},{"busyWorkers",ioMetrics.busy.load()},{"workerUtilization",seconds&&workers?std::min(100.0,ioMetrics.workerNs.load()/1e9/seconds/workers*100):0}};}
static void metricsPhase(const std::string&phase){std::lock_guard<std::mutex> guard(metricsLock);if(!metricsStage.empty()){auto previous=metricsSnapshot();metricsHistory.push_back(previous);std::cout<<"Stage statistics: "<<previous.dump()<<"\n";}resetIoMetrics();metricsStage=phase;metricsStarted=ioClock();metricsEnded=0;}
extern "C" void ampr_backend_metrics(char*out,size_t size){std::lock_guard<std::mutex> guard(metricsLock);auto state=metricsSnapshot();state["stages"]=metricsHistory;auto text=state.dump();if(text.size()>=size){state["stages"]=Json::array();state["historyTruncated"]=true;text=state.dump();}snprintf(out,size,"%s",text.c_str());}

class BackendLog:public std::streambuf {
    const ampr_backend_callbacks *callbacks;std::string line;
    int overflow(int c)override{if(c!=EOF){line+=char(c);if(c=='\n')sync();}return c;}
    int sync()override{if(!line.empty()){if(callbacks&&callbacks->log)callbacks->log(callbacks->context,line.c_str());line.clear();}return 0;}
public:BackendLog(const ampr_backend_callbacks *cb):callbacks(cb){}
};
extern "C" int ampr_backend_pack(const char *root,const char *index,const char *output,int level,const ampr_backend_callbacks *cb,char *error,size_t error_size){
    std::unique_lock<std::mutex> guard(backendLock,std::try_to_lock);if(error&&error_size)error[0]=0;
    auto fail=[&](const char*s){if(error&&error_size)snprintf(error,error_size,"%s",s);return -1;};
    if(!guard.owns_lock())return fail("AMPR backend is already busy");if(!root||!index||!output||level<1||level>12)return fail("Invalid AMPR pack request");
    BackendLog log(cb);auto old=std::cout.rdbuf(&log);auto olderr=std::cerr.rdbuf(&log);int result=-1;bool ownsOutput=false;
    try{cancelled=0;cancellationHook=[&](){return cb&&cb->cancelled&&cb->cancelled(cb->context);};auto poll=[&](){ensureActive();};
        poll();progressHook=[&](uint64_t done,uint64_t total){ownsOutput=true;poll();if(cb&&cb->progress)cb->progress(cb->context,done,total);};
        if(cb&&cb->phase)cb->phase(cb->context,"packing");pack(fs::u8path(root),fs::u8path(index),fs::u8path(output),false,level);
        poll();if(cb&&cb->phase)cb->phase(cb->context,"verifying");verify(fs::u8path(output)/"ampr_assets.index",fs::u8path(root));
        poll();if(cb&&cb->phase)cb->phase(cb->context,"verified");result=0;
    }catch(const std::exception&e){result=fail(e.what());std::cerr<<"ERROR: "<<e.what()<<"\n";if(ownsOutput){std::ofstream marker(fs::u8path(output)/"INCOMPLETE.txt");marker<<"Packing/verification failed or cancelled; output is not approved.\n"<<e.what()<<"\n";}}
    cancellationHook=nullptr;progressHook=nullptr;log.pubsync();std::cout.rdbuf(old);std::cerr.rdbuf(olderr);return result;
}
static fs::path pipelineSettingsPath(){return fs::path(AMPR_STATE_ROOT)/"pipeline-threads.json";}
static Json pipelineJson(const PipelineThreads&p){auto stage=[](StageThreads s){return Json{{"readers",s.readers},{"workers",s.workers},{"writers",s.writers},{"coordinator",1},{"total",1+s.readers+s.workers+s.writers}};};return Json{{"packing",stage(p.packing)},{"loose",stage(p.loose)},{"verification",stage(p.verification)}};}
static PipelineThreads pipelineParse(const Json&j){PipelineThreads p;auto stage=[&](const char*name){auto&s=j.at(name);for(auto key:{"readers","workers","writers"})check(s.at(key).is_number_integer()&&s.at(key).get<int>()>=0&&s.at(key).get<int>()<=6,"Invalid thread count");return StageThreads{s.at("readers"),s.at("workers"),s.at("writers")};};p.packing=stage("packing");p.loose=stage("loose");p.verification=stage("verification");validatePipeline(p);return p;}
static PipelineThreads loadPipeline(){if(!fs::exists(pipelineSettingsPath()))return PipelineThreads{};return pipelineParse(Json::parse(read(pipelineSettingsPath())));}
extern "C" int ampr_backend_thread_settings(const char*input,char*out,size_t size){
    std::unique_lock<std::mutex> guard(backendLock,std::try_to_lock);try{check(guard.owns_lock(),"Wait for the conversion to finish before changing worker settings.");auto p=input?pipelineParse(Json::parse(input)):loadPipeline();
        if(input){fs::create_directories(pipelineSettingsPath().parent_path());auto temporary=pipelineSettingsPath();temporary+=".tmp";{std::ofstream f(temporary);f<<pipelineJson(p).dump(2);f.flush();check(bool(f),"Cannot save worker settings");}fs::rename(temporary,pipelineSettingsPath());}
        auto result=pipelineJson(p);result["ok"]=true;result["threadLimit"]=8;snprintf(out,size,"%s",result.dump().c_str());return 0;
    }catch(const std::exception&e){snprintf(out,size,"%s",e.what());return -1;}
}
static void backendHooks(const ampr_backend_callbacks*cb,bool fresh=false){
    if(fresh){pipelineThreads=loadPipeline();std::lock_guard<std::mutex> guard(metricsLock);metricsHistory=Json::array();metricsEnded=0;metricsStage.clear();metricsStarted=ioClock();resetIoMetrics();ioMetrics.workers=0;}
    cancelled=0;cancellationHook=[cb](){return cb&&cb->cancelled&&cb->cancelled(cb->context);};
    phaseHook=[cb](const std::string&s){metricsPhase(s);if(cb&&cb->phase)cb->phase(cb->context,s.c_str());};
    progressHook=[cb](uint64_t done,uint64_t total){ensureActive();if(cb&&cb->progress)cb->progress(cb->context,done,total);};
}
static void clearBackendHooks(){ {std::lock_guard<std::mutex> guard(metricsLock);metricsEnded=ioClock();}outputCreatedHook=nullptr;phaseHook=nullptr;progressHook=nullptr;cancellationHook=nullptr;productionPack=false;}
static void checkNewSeparate(const fs::path&source,const fs::path&output){check(fs::is_directory(source)&&!fs::exists(output),"source must exist and destination must be new");auto root=fs::weakly_canonical(source),dest=fs::weakly_canonical(output);auto r=root.begin(),d=dest.begin();for(;r!=root.end()&&d!=dest.end()&&*r==*d;++r,++d){}check(r!=root.end(),"destination cannot be inside source");}
static void incomplete(const fs::path&out,const char*message){if(fs::is_directory(out)){try{trackPartial(out,"output");}catch(const std::exception&e){std::cerr<<"Cleanup registration warning: "<<e.what()<<"\n";}std::ofstream marker(out/"INCOMPLETE.txt");marker<<"Output is not approved.\n"<<message<<"\n";}}
extern "C" int ampr_backend_pack_game_options(const char*root,const char*output,int level,const char*runtime,const char*learned,int verify_output,const ampr_backend_callbacks*cb,char*error,size_t error_size){
    std::unique_lock<std::mutex> guard(backendLock,std::try_to_lock);if(error&&error_size)error[0]=0;if(!guard.owns_lock()||!root||!output||!runtime||level<1||level>12){if(error&&error_size)snprintf(error,error_size,"Invalid request or backend busy");return -1;}
    BackendLog log(cb);auto old=std::cout.rdbuf(&log),olderr=std::cerr.rdbuf(&log);fs::path workspace;bool owns=false;int result=-1;
    try{loadPartials();backendHooks(cb,true);checkNewSeparate(fs::u8path(root),fs::u8path(output));auto parent=fs::u8path(output).parent_path();fs::create_directories(parent);check(fs::is_directory(parent),"cannot create destination parent folders");
        // Own one exclusive scratch directory. It contains only small metadata,
        // never an extracted game and never files inside the mounted source.
        for(int attempt=0;attempt<100;attempt++){auto candidate=parent/(fs::u8path(output).filename().u8string()+".ampr-work-"+std::to_string(attempt));if(fs::create_directory(candidate)){workspace=candidate;trackPartial(workspace,"workspace");break;}}check(!workspace.empty(),"cannot reserve metadata workspace");
        phase("Building source index");auto index=workspace/"source.index";makeIndex(fs::u8path(root),index);auto profile=workspace/"profile.toml";phase("Generating compression profile");generateUniversalProfile(fs::u8path(root),profile,level,level<=4,learned?fs::u8path(learned):fs::path{});
        productionPack=true;outputCreatedHook=[&](){owns=true;trackPartial(fs::u8path(output),"output");};packProfile(fs::u8path(root),index,fs::u8path(output),profile,fs::u8path(runtime));if(verify_output)verify(fs::u8path(output)/"ampr_assets.index",fs::u8path(root));else{std::ofstream marker(fs::u8path(output)/"UNVERIFIED.txt");marker<<"Final decoded-content verification was skipped. Keep the original until independently checked and launch-tested.\n";check(bool(marker),"Cannot write unverified-output notice");}ensureActive();phase(verify_output?"Complete: output verified":"Complete: verification skipped");forgetPartial(fs::u8path(output));result=0;
    }catch(const std::exception&e){if(error&&error_size)snprintf(error,error_size,"%s",e.what());std::cerr<<"ERROR: "<<e.what()<<"\n";if(owns)incomplete(fs::u8path(output),e.what());}
    clearBackendHooks();if(!workspace.empty()){std::error_code ec;try{removeOwnedTree(workspace);forgetPartial(workspace);}catch(const std::exception&e){std::cerr<<"Temporary folder cleanup failed: "<<e.what()<<"\n";}}log.pubsync();std::cout.rdbuf(old);std::cerr.rdbuf(olderr);return result;
}
extern "C" int ampr_backend_pack_game(const char*root,const char*output,int level,const char*runtime,const char*learned,const ampr_backend_callbacks*cb,char*error,size_t size){return ampr_backend_pack_game_options(root,output,level,runtime,learned,1,cb,error,size);}
extern "C" int ampr_backend_measure(const char*root,uint64_t*logical,uint64_t*required,char*error,size_t error_size){
    try{check(root&&logical&&required,"invalid scan request");*logical=0;uint64_t physical=0,metadata=512,files=0;auto add=[](uint64_t&a,uint64_t n){check(n<=UINT64_MAX-a,"size scan overflow");a+=n;};
        for(auto&entry:fs::recursive_directory_iterator(fs::u8path(root))){check(!entry.is_symlink(),"source symlink unsupported");if(!entry.is_regular_file())continue;auto size=entry.file_size();auto name=entry.path().lexically_relative(fs::u8path(root)).generic_u8string();if(name=="ampr_emu.index"||name=="ampr_emu.index.tmp"||name=="ampr_commands.bin"||name=="apr_emu.log")continue;check(size<UINT64_MAX-65536,"file size overflow");add(*logical,size);add(physical,align(size,65536));add(metadata,128+name.size()*2+16*((size+16383)/16384));++files;}
        check(metadata<512ull*1024*1024,"metadata exceeds supported budget");add(physical,metadata);add(physical,(5+physical/(16ull*1024*1024*1024-131072)+files/65536)*65536);add(physical,16ull*1024*1024);*required=physical;if(error&&error_size)error[0]=0;return 0;
    }catch(const std::exception&e){if(error&&error_size)snprintf(error,error_size,"%s",e.what());return -1;}
}
extern "C" int ampr_backend_copy_options(const char*packed,const char*internal,int verify_copy,const ampr_backend_callbacks*cb,char*error,size_t error_size){
    std::unique_lock<std::mutex>guard(backendLock,std::try_to_lock);if(!guard.owns_lock()||!packed||!internal)return -1;BackendLog log(cb);auto old=std::cout.rdbuf(&log),olderr=std::cerr.rdbuf(&log);bool owns=false;int result=-1;
    try{backendHooks(cb);checkNewSeparate(fs::u8path(packed),fs::u8path(internal));check(!fs::exists(fs::u8path(packed)/"INCOMPLETE.txt"),"packed source is unapproved");uint64_t total=0,done=0;std::vector<fs::path> paths;for(auto&entry:fs::recursive_directory_iterator(fs::u8path(packed))){check(!entry.is_symlink(),"copy source symlink unsupported");if(entry.is_regular_file()){paths.push_back(entry.path());total+=entry.file_size();}}
        fs::create_directories(fs::u8path(internal).parent_path());check(fs::create_directory(fs::u8path(internal)),"internal destination must be new");owns=true;trackPartial(fs::u8path(internal),"output");phase("Copying output to internal");for(auto&path:paths){ensureActive();copyLoose(path,safe(fs::u8path(internal),path.lexically_relative(fs::u8path(packed)).generic_u8string()),done,total);}
        if(verify_copy){phase("Verifying internal copy");done=0;if(progressHook)progressHook(0,total);BlockWorkers checks(4);std::deque<std::pair<std::future<void>,uint64_t>> pending;
        auto drain=[&](){while(pending.front().first.wait_for(std::chrono::milliseconds(100))!=std::future_status::ready)ensureActive();pending.front().first.get();done+=pending.front().second;pending.pop_front();if(progressHook)progressHook(done,total);};
        for(auto&path:paths){ensureActive();auto target=safe(fs::u8path(internal),path.lexically_relative(fs::u8path(packed)).generic_u8string());check(fs::file_size(path)==fs::file_size(target),"internal copy size mismatch");std::ifstream a(path,std::ios::binary),b(target,std::ios::binary);check(bool(a)&&bool(b),"internal copy open failed");while(a){ensureActive();Bytes x(2*1048576),y(2*1048576);size_t n;{IoMeasure timer(ioMetrics.readNs);a.read((char*)x.data(),x.size());n=size_t(a.gcount());b.read((char*)y.data(),n);check(b.gcount()==int64_t(n),"internal copy truncated");ioMetrics.readBytes+=n*2;}if(n){x.resize(n);y.resize(n);pending.emplace_back(checks.task([x=std::move(x),y=std::move(y)](){check(x==y,"internal copy byte mismatch");}),n);if(pending.size()>=4)drain();}}check(a.eof()&&b.peek()==EOF,"internal copy read failed");}while(!pending.empty())drain();}else{std::ofstream marker(fs::u8path(internal)/"UNVERIFIED.txt");marker<<"Internal-copy verification was skipped. Keep the original.\n";check(bool(marker),"Cannot write unverified-copy notice");}phase(verify_copy?"Complete: internal copy verified":"Complete: internal copy verification skipped");forgetPartial(fs::u8path(internal));result=0;
    }catch(const std::exception&e){if(error&&error_size)snprintf(error,error_size,"%s",e.what());std::cerr<<"ERROR: "<<e.what()<<"\n";if(owns)incomplete(fs::u8path(internal),e.what());}
    clearBackendHooks();log.pubsync();std::cout.rdbuf(old);std::cerr.rdbuf(olderr);return result;
}

extern "C" int ampr_backend_copy_verified(const char*packed,const char*internal,const ampr_backend_callbacks*cb,char*error,size_t size){return ampr_backend_copy_options(packed,internal,1,cb,error,size);}
extern "C" int ampr_backend_mounted_titles(const char*text,char*titles,size_t size,char*error,size_t error_size){try{auto j=nlohmann::json::parse(text);check(j.at("status").get<int>()==0,"ShadowMount snapshot failed");std::string result;for(auto &g:j.at("games")){if(g.value("managed",false)&&g.value("mounted",false)){auto title=g.at("title_id").get<std::string>();check(title.size()==9&&title.substr(0,4)=="PPSA"&&title.find_first_not_of("0123456789",4)==std::string::npos,"Invalid mounted title");result+=title+"\n";}}check(result.size()<size,"Too many mounted games");memcpy(titles,result.c_str(),result.size()+1);return 0;}catch(const std::exception&e){snprintf(error,error_size,"%s",e.what());return -1;}}

extern "C" int ampr_backend_delete_partial(char*error,size_t size){
 std::unique_lock<std::mutex> guard(backendLock,std::try_to_lock);
 try{check(guard.owns_lock(),"Wait for conversion to stop before deleting partial output.");loadPartials();for(auto it=partialOutputs.begin();it!=partialOutputs.end();){const auto path=it->first;struct stat st{};if(lstat(path.c_str(),&st)){if(errno==ENOENT){it=partialOutputs.erase(it);savePartials();continue;}throw std::runtime_error("Cannot inspect partial folder: "+path.u8string()+": "+strerror(errno));}check(S_ISDIR(st.st_mode)&&uint64_t(st.st_dev)==it->second.device&&uint64_t(st.st_ino)==it->second.inode,"Partial folder changed; refusing deletion: "+path.u8string());std::ifstream marker(path/".ampr-owned");std::string token((std::istreambuf_iterator<char>(marker)),{});check(token==it->second.token,"Folder ownership marker changed; refusing deletion: "+path.u8string());removeOwnedTree(path);it=partialOutputs.erase(it);savePartials();}return 0;}catch(const std::exception&e){snprintf(error,size,"%s",e.what());return -1;}
}

