extern "C" int ampr_backend_recover_partial(const char*output,char*error,size_t size){std::unique_lock<std::mutex> guard(backendLock,std::try_to_lock);try{check(guard.owns_lock(),"Backend is busy.");loadPartials();auto path=fs::u8path(output);struct stat st{};if(lstat(path.c_str(),&st)&&errno==ENOENT)return 0;check(S_ISDIR(st.st_mode),"Last output path is not a folder.");check(fs::is_regular_file(path/"INCOMPLETE.txt"),"Last output is not incomplete; refusing recovery.");std::ifstream marker(path/".ampr-owned");std::string token((std::istreambuf_iterator<char>(marker)),{});check(token.rfind("AMPRStudio:",0)==0&&token.size()>16&&token.substr(token.rfind(':')+1)==std::to_string(st.st_ino),"Last output ownership marker is invalid.");partialOutputs[fs::canonical(path)]={uint64_t(st.st_dev),uint64_t(st.st_ino),token,"output"};savePartials();for(int n=0;n<100;n++){auto work=fs::path(path.u8string()+".ampr-work-"+std::to_string(n));struct stat ws{};if(lstat(work.c_str(),&ws)){if(errno==ENOENT)continue;throw std::runtime_error("Cannot inspect old work folder.");}check(S_ISDIR(ws.st_mode),"Old work folder changed.");DIR*dir=opendir(work.c_str());check(dir,"Cannot inspect old work folder contents.");bool valid=true;while(auto*entry=readdir(dir)){std::string name=entry->d_name;if(name!="."&&name!=".."&&name!="source.index"&&name!="profile.toml"&&name!=".ampr-owned")valid=false;}closedir(dir);check(valid,"Old work folder contains unrelated files; refusing cleanup.");std::ifstream source(work/"source.index",std::ios::binary);char magic[8]{};source.read(magic,8);std::ifstream profile(work/"profile.toml");std::string header;std::getline(profile,header);check(!memcmp(magic,"AMPRIDX3",8)&&header=="# Universal profile generated by scanning game structure","Old work folder is not recognized metadata.");trackPartial(work,"workspace");}return 0;}catch(const std::exception&e){snprintf(error,size,"%s",e.what());return -1;}}
